// =============================================
// SEGMENTATION : Tranche d'âge + Saison + Lieu
// Indicateurs arbre 2.2 :
//   Ind.1 : Nb parcours / groupe d'âge
//   Ind.2 : Taux d'inscription par tranche
// =============================================

const adherents = $input.all().map(i => i.json);

// --- Détection saison selon le mois actuel ---
const mois = new Date().getMonth() + 1; // 1-12
let saison, saisonLabel, emoji;
if ([12, 1, 2].includes(mois)) {
  saison = 'hiver'; saisonLabel = 'Hiver'; emoji = '❄️';
} else if ([3, 4, 5].includes(mois)) {
  saison = 'printemps'; saisonLabel = 'Printemps'; emoji = '🌸';
} else if ([6, 7, 8].includes(mois)) {
  saison = 'ete'; saisonLabel = 'Été'; emoji = '☀️';
} else {
  saison = 'automne'; saisonLabel = 'Automne'; emoji = '🍂';
}

// --- Calcul de l'âge et tranche ---
function calculerAge(dateNaissance) {
  const naissance = new Date(dateNaissance);
  const aujourd = new Date();
  let age = aujourd.getFullYear() - naissance.getFullYear();
  const m = aujourd.getMonth() - naissance.getMonth();
  if (m < 0 || (m === 0 && aujourd.getDate() < naissance.getDate())) age--;
  return age;
}

function trancheAge(age) {
  if (age >= 6 && age <= 11) return { tranche: 'louveteaux', label: 'Louveteaux / Farfadets', min: 6, max: 11 };
  if (age >= 12 && age <= 16) return { tranche: 'scouts', label: 'Scouts / Guides', min: 12, max: 16 };
  if (age >= 17 && age <= 21) return { tranche: 'routiers', label: 'Routiers / Pionnières', min: 17, max: 21 };
  return { tranche: 'autre', label: 'Membres', min: 0, max: 99 };
}

// --- Contenus thématiques par saison ---
const themesSaison = {
  hiver: {
    louveteaux: {
      activites: ['jeux dans la neige', 'bricolage de Noël', 'chasse au trésor intérieure'],
      conseil: 'Pense à préparer des vêtements chauds pour les sorties !',
      actu: 'Le camp d\'hiver approche — inscris-toi avant le 15 !'
    },
    scouts: {
      activites: ['bivouac hivernal', 'navigation nocturne', 'survie en milieu froid'],
      conseil: 'Parfait pour travailler les techniques de survie hivernale.',
      actu: 'Préparation camp de janvier — réunion de planification ce mois.'
    },
    routiers: {
      activites: ['projet solidarité hiver', 'formation premiers secours', 'chantier communauté'],
      conseil: 'Une belle saison pour les projets de service à la communauté.',
      actu: 'Ateliers de formation disponibles — inscris-toi en ligne.'
    }
  },
  printemps: {
    louveteaux: {
      activites: ['observation nature', 'plantation jardin scout', 'jeux de piste en forêt'],
      conseil: 'La nature se réveille — prépare ta loupe et ton carnet !',
      actu: 'Sortie nature prévue — confirmation de présence requise.'
    },
    scouts: {
      activites: ['randonnée longue distance', 'orientation en forêt', 'camp de Pâques'],
      conseil: 'Saison idéale pour les grandes randonnées — entraîne-toi !',
      actu: 'Camp de Pâques — inscriptions ouvertes jusqu\'au 20.'
    },
    routiers: {
      activites: ['projet ODD environnement', 'nettoyage rivière', 'camp service'],
      conseil: 'Idéal pour lancer tes projets à impact environnemental.',
      actu: 'Journée mondiale scoutisme — organisation en cours, rejoins le groupe.'
    }
  },
  ete: {
    louveteaux: {
      activites: ['camp d\'été', 'baignade et water games', 'veillée contes'],
      conseil: 'N\'oublie pas la crème solaire et la gourde pour le camp !',
      actu: 'Camp d\'été confirmé — liste de matériel envoyée aux parents.'
    },
    scouts: {
      activites: ['camp itinérant', 'kayak / escalade', 'nuit d\'autonomie'],
      conseil: 'La grande aventure de l\'année — donne le meilleur de toi !',
      actu: 'Camp été — départ le 5 juillet, retour le 20. Prépare ton sac !'
    },
    routiers: {
      activites: ['voyage de clan', 'Jamboree', 'projet international'],
      conseil: 'L\'été routier, c\'est l\'exploration à grande échelle.',
      actu: 'Candidatures Jamboree — date limite ce mois.'
    }
  },
  automne: {
    louveteaux: {
      activites: ['récolte et cuisine', 'rallye automne', 'fabrication cabane'],
      conseil: 'Super saison pour les activités manuelles en plein air !',
      actu: 'Rentrée scoute — accueil des nouveaux louveteaux ce mois !'
    },
    scouts: {
      activites: ['camp de rentrée', 'préparation projet annuel', 'course d\'orientation'],
      conseil: 'Moment clé pour planifier les grandes aventures de l\'année.',
      actu: 'Conseil de troupe — programme annuel à construire ensemble.'
    },
    routiers: {
      activites: ['AG clan', 'définition projets annuels', 'recrutement nouveaux membres'],
      conseil: 'C\'est la saison pour poser les bases de tes projets.',
      actu: 'AG de rentrée routiers — présence obligatoire, ordre du jour ci-joint.'
    }
  }
};

// --- Application à chaque adhérent ---
return adherents.map(adherent => {
  const age = calculerAge(adherent.date_naissance);
  const { tranche, label } = trancheAge(age);
  const contenu = themesSaison[saison]?.[tranche] || themesSaison[saison]?.scouts;

  return {
    json: {
      ...adherent,
      age,
      tranche_age: tranche,
      tranche_label: label,
      saison,
      saison_label: saisonLabel,
      saison_emoji: emoji,
      activites_proposees: contenu.activites,
      conseil_saison: contenu.conseil,
      actu_groupe: contenu.actu,
      mois_envoi: new Date().toISOString().slice(0, 7)
    }
  };
});

// Template Louveteaux (6-11 ans) — ton ludique et coloré

const d = $json; // ✅ plus simple que $input.first()

// Sécuriser activites_proposees (au cas où undefined)
const activites = (d.activites_proposees || [])
  .map(a => `<li style='margin:4px 0;'>🐺 ${a}</li>`)
  .join('');

// Sujet email
const sujet = `${d.saison_emoji || ''} Bonjour ${d.prenom} ! Les aventures ${d.saison_label} arrivent !`;

// Corps email
const corps = `
<div style='font-family:Arial,sans-serif;max-width:580px;'>

  <div style='background:#fff3cd;border-radius:12px;padding:20px;text-align:center;margin-bottom:16px;'>
    <div style='font-size:40px;'>${d.saison_emoji || ''}</div>
    <h2 style='color:#856404;margin:8px 0;'>Salut ${d.prenom} le Louveteau !</h2>
    <p style='color:#856404;margin:0;'>Saison ${d.saison_label} — Meute <strong>${d.unite}</strong></p>
  </div>

  <p style='font-size:15px;'>Ce mois-ci, voici ce qui t'attend :</p>
  <ul style='font-size:14px;line-height:1.8;'>${activites}</ul>

  <div style='background:#d4edda;border-radius:8px;padding:12px;margin:16px 0;'>
    <strong>Le conseil de la meute :</strong><br>${d.conseil_saison || ''}
  </div>

  <div style='background:#cce5ff;border-radius:8px;padding:12px;'>
    <strong>Actu du groupe :</strong><br>${d.actu_groupe || ''}
  </div>

  <p style='font-size:12px;color:#888;margin-top:20px;'>
    Message envoyé à ${d.email_parent} — Groupe Scout | ${d.lieu}
  </p>

</div>`;

// Output
return [{
  json: {
    ...d,
    sujet_email: sujet,
    corps_email: corps
  }
}];

// Template Scouts / Guides (12-16 ans) — ton aventure et défi
const d = $input.first().json;
const activites = (d.activites_proposees || []).map(a => `<li style='margin:6px 0;'>⚜️ ${a}</li>`).join('');

const sujet = `${d.saison_emoji || ''} ${d.saison_label || 'Ce mois'} scout — Tes défis du mois, ${d.prenom} !`;

const corps = `
<div style='font-family:Arial,sans-serif;max-width:580px;'>
  <div style='background:#d1ecf1;border-radius:12px;padding:20px;margin-bottom:16px;'>
    <h2 style='color:#0c5460;margin:0 0 4px;'>${d.saison_emoji || ''} ${d.saison_label || ''} — Troupe ${d.unite}</h2>
    <p style='color:#0c5460;margin:0;font-size:14px;'>Bonjour <strong>${d.prenom}</strong> — ${d.age} ans — ${d.lieu || ''}</p>
  </div>

  <p><strong>Ce mois-ci dans ta troupe :</strong></p>
  <ul style='font-size:14px;line-height:1.9;'>${activites}</ul>

  <div style='border-left:4px solid #17a2b8;padding:10px 16px;margin:16px 0;background:#f8f9fa;border-radius:0 8px 8px 0;'>
    <strong>Conseil de saison :</strong><br>
    <em>${d.conseil_saison || ''}</em>
  </div>

  <div style='background:#fff3cd;border-radius:8px;padding:12px;'>
    <strong>📢 Actu du groupe :</strong><br>${d.actu_groupe || ''}
  </div>

  <p style='font-size:12px;color:#888;margin-top:20px;'>Groupe Scout — ${d.lieu || ''} | Contact : ${d.email_parent}</p>
</div>`;

return [{ json: { ...d, sujet_email: sujet, corps_email: corps } }];

// Template Routiers / Pionnières (17-21 ans) — ton projet et engagement
const d = $input.first().json;
const activites = (d.activites_proposees || []).map(a => `<li style='margin:6px 0;'>${a}</li>`).join('');

const sujet = `${d.saison_emoji || ''} ${d.saison_label || 'Ce mois'} — Programme de ton clan, ${d.prenom}`;

const corps = `
<div style='font-family:Arial,sans-serif;max-width:580px;'>
  <div style='background:#d4edda;border-radius:12px;padding:20px;margin-bottom:16px;'>
    <h2 style='color:#155724;margin:0 0 4px;'>Bonjour ${d.prenom},</h2>
    <p style='color:#155724;margin:0;font-size:14px;'>Clan ${d.unite} — ${d.saison_label || ''} — ${d.age} ans — ${d.lieu || ''}</p>
  </div>

  <p style='font-size:15px;'>Au programme ce mois pour ton clan :</p>
  <ul style='font-size:14px;line-height:1.9;color:#333;'>${activites}</ul>

  <div style='background:#f8f9fa;border:1px solid #dee2e6;border-radius:8px;padding:14px;margin:16px 0;'>
    <strong>Perspective de saison :</strong><br>
    ${d.conseil_saison || ''}
  </div>

  <div style='background:#e2e3e5;border-radius:8px;padding:12px;'>
    <strong>Information clan :</strong><br>${d.actu_groupe || ''}
  </div>

  <p style='font-size:12px;color:#888;margin-top:20px;'>Groupe Scout — ${d.lieu || ''} | Répondre à cet email pour toute question.</p>
</div>`;

return [{ json: { ...d, sujet_email: sujet, corps_email: corps } }];

// Rapport trimestriel Ind.1 et Ind.2
const rows = $input.all().map(i => i.json);
if (!rows.length) return [{ json: { html: '<p>Aucune donnée disponible.</p>' } }];

const tranches = ['louveteaux', 'scouts', 'routiers'];
const labels = { louveteaux: 'Louveteaux (6-11 ans)', scouts: 'Scouts/Guides (12-16 ans)', routiers: 'Routiers (17-21 ans)' };

// Comptage par tranche
const stats = {};
tranches.forEach(t => {
  const group = rows.filter(r => r.tranche_age === t);
  const uniques = [...new Set(group.map(r => r.prenom + r.email_parent))];
  stats[t] = {
    total_envois: group.length,
    adherents_uniques: uniques.length,
    mois_actifs: [...new Set(group.map(r => r.mois))].length,
    saisons: [...new Set(group.map(r => r.saison))].join(', ')
  };
});

// Tableau HTML
const lignes = tranches.map(t => {
  const s = stats[t];
  return `<tr>
    <td style='padding:8px'>${labels[t]}</td>
    <td style='padding:8px;text-align:center'><strong>${s.adherents_uniques}</strong></td>
    <td style='padding:8px;text-align:center'>${s.total_envois}</td>
    <td style='padding:8px;text-align:center'>${s.mois_actifs}</td>
    <td style='padding:8px;text-align:center'>${s.saisons}</td>
  </tr>`;
}).join('');

const total = rows.length;
const periode = rows[0]?.mois || 'trimestre';

const html = `
<h2 style='color:#2c5f2e;'>Rapport trimestriel — Communication personnalisée</h2>
<p><strong>Ind.1 — Parcours par groupe d'âge :</strong></p>
<table border='1' cellpadding='0' cellspacing='0' style='border-collapse:collapse;width:100%;font-size:13px;'>
  <thead>
    <tr style='background:#2c5f2e;color:white;'>
      <th style='padding:8px'>Tranche d'âge</th>
      <th style='padding:8px'>Adhérents uniques</th>
      <th style='padding:8px'>Envois total</th>
      <th style='padding:8px'>Mois actifs</th>
      <th style='padding:8px'>Saisons couvertes</th>
    </tr>
  </thead>
  <tbody>${lignes}</tbody>
</table>
<p style='margin-top:16px;'><strong>Ind.2 — Total envois ce trimestre :</strong> ${total} messages personnalisés.</p>
<p style='font-size:12px;color:#666;'>Données issues de l'onglet Suivi_messages — Google Sheets.</p>
`;

return [{ json: { html, total, periode } }];
